import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;

public class Main {

    public static void main(String[] args) throws Exception {
        InputStream is = System.in;
        OutputStream os = System.out;

        BufferedReader br = new BufferedReader(new InputStreamReader(is));
        PrintWriter pw = new PrintWriter(os);

        String inputLine = br.readLine();
        String[] tokens = inputLine.split(" ");
        int n = Integer.parseInt(tokens[0]);
        long k = Long.parseLong(tokens[1]);

        Task task = new Task();
        task.run(n, k, pw);
        pw.close();
    }
}

class Task {

    private static int mod = 998244353;

    public void run(int n, long k, PrintWriter out) {
        long[] fact = new long[200001];
        long[] invFact = new long[200001];
        fact[0] = invFact[0] = 1;
        for (int i = 1; i < 200001; i++) {
            fact[i] = fact[i - 1] * i % mod;
            invFact[i] = invFact[i - 1] * powMod(i, mod - 2) % mod;
        }
        if (k >= n) {
            out.println(0);
            return;
        }
        if (k == 0) {
            out.println(fact[n]);
            return;
        }
        int m = (int)(n - k);
        long sum = 0;
        for (int i = 0; i <= m; i++) {
            long c = getCombination(fact, invFact, m, i);
            long val = powMod(m - i, n);
            if (i % 2 == 0) {
                sum = (sum + c * val) % mod;
            } else {
                sum = (sum - c * val + mod) % mod;
            }
        }
        long res = 2 * fact[n] % mod * invFact[n - m] % mod * sum % mod * invFact[m] % mod;
        out.println(res);
    }

    private long powMod(long base, long exp) {
        long result = 1;
        long baseVal = base;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * baseVal % mod;
            baseVal = baseVal * baseVal % mod;
            exp >>= 1;
        }
        return result;
    }

    private long getCombination(long[] fact, long[] invFact, int n, int m) {
        return fact[n] * invFact[m] % mod * invFact[n - m] % mod;
    }
}
